save(919,{2:'朦胧星域是帝国划分银河的五大星域之一，位于神圣泰拉以北，其星域堡垒坐落于塞浦拉·蒙迪。最显著的地理特征之一是恐惧之眼，许多混沌星际战士盘踞于此。',4:'第十三次黑色远征结束、罗保特·基里曼复活后，朦胧星域的大部分地区被隔绝在帝国暗面。',11:'Belis Corona 贝利斯·卡罗纳',16:'Cypra Mundi 塞浦拉·蒙迪',17:'Dimmamar 迪马默',22:"M'Pandex 姆潘德克斯",38:'Vostroya 沃斯特洛亚',41:'Demios Binary 德米奥斯双星',52:'Sanctus Wall 圣墙防线',55:'Coronid Deeps 科罗尼德深渊',58:'Craftworld Altansar 奥坦萨方舟世界',60:'Koronus Expanse 克洛诺斯广域',61:'Molianis Reach 莫里阿尼斯疆域',69:'Ixaniad Sector 伊萨尼亚德星区',77:'Belis Corona System 贝利斯·卡罗纳星系'},notes={41:'Binary 不是行星序数二，依864篇同名铸造世界译德米奥斯双星；具体天体构成待核。',61:'Reach 在星际地域语境为疆域，不是地表河段。',89:'本节银河方位按原稿叙述照录，并非现实天文学的绝对上下方向。'},terms=[('Molianis Reach','莫里阿尼斯疆域'),('Ixaniad Sector','伊萨尼亚德星区'),('Belis Corona System','贝利斯·卡罗纳星系')])
save(920,{2:'炼狱之门位于朦胧星域落入帝国暗面的部分，靠近名为“荒凉缠绕”的亚空间风暴。这片地区目前是帝国战区。',5:'炼狱之门包含两个奇点，它们在引力能量构成的涡流中彼此环绕。巫师卡齐克·盖尔率领混沌星际战士，以此为隐蔽基地，多次劫掠帝国世界与运输船队，并在数十颗乃至更多世界煽起叛乱。盖尔利用这些冲突扩充财富与力量，招揽追随者，赢得混沌诸神青睐。然而，他如何能够穿行于两个奇点之间而不被强大引力吞噬，仍是未解之谜。',7:'审判庭将所有相关情报列为机密；只有具备相应权限的人，才能查阅有关炼狱之门的资料。'},notes={5:'shipping 与Imperial worlds并列，指遭劫掠的航运及运输船队，原译“从避难所运送物资”错置谓语。without falling victim to gravity 是免于被引力毁灭，不意味着完全不受引力作用。'},terms=[('Inferni Gates','炼狱之门'),('Bleak Coil','荒凉缠绕'),('Kazik Gyle','卡齐克·盖尔')])
save(921,{2:'纳克蒙德走廊是朦胧星域的一片空域，以纳克蒙德次星区为中心。',4:'Nachmund Sub-Sector 纳克蒙德次星区',7:'纳克蒙德走廊靠近卡迪亚残骸与恐惧之眼，曾一度是穿越大裂隙的唯一稳定通道。因此，它战略价值极高，也承载着大量帝国难民的迁徙。不屈远征后期，人们又发现了第二条通道，称为阿提兰之门。',9:'尽管帝国一度守住大部分地区，纳克蒙德走廊北端和南端部分区域仍遭混沌围攻。纳克蒙德裂隙战争中，帝国几乎失去了整个北部区域，遂试图建立名为“圣墙防线”的防御网络，阻挡夺星者哈尔肯率领的黑色军团。圣墙以北仍有许多世界效忠帝国，但它们基本只能独力抵御即将到来的攻势。赤地星大部分地区被混沌占据后，帝国处境进一步恶化。',16:'森托登陆地——圣地世界。',18:'乔拉里斯——非物质界涌动站。',21:'戴瑟——蛮荒灵族世界。',23:'圣化之地——国教会控制的世界。',27:'达罗瓦尔——混沌骑士世界。',31:'恩凯利恩漂流带——小行星区。',33:'乔治七号——神学院世界。',37:'贾格迪斯·马格纳——农业世界。',47:'卡尔之缘——小行星采矿殖民地。',55:'圣马里努斯光环——设有防御设施的吸积盘。',61:'丰迪斯双星——星语部站点，已落入混沌之手。',67:'瓦格希扎尔——帝国卫队集结世界，已落入混沌之手。',79:'沃里拉·芬——异形殖民地。',96:'诺纳沃尔——堡垒世界（Bastion World，哨兵世界别称）。',111:'资料集《纳克蒙德战区：裂隙战争》则将赤血星系，以及其中的赤地星，标在相邻的格兰达尔次星区。'},notes={7:'避免把路线本身误写成制造难民的地点；本篇已明确“曾一度”唯一，与880篇旧资料时点相互对照。',18:'Immaterium Surge Station 暂沿功能字面译，具体设施性质尚待核，未无据认定为普通太空港。',21:'Exodite World 为蛮荒灵族世界，区别人类Feral World蛮荒世界。',33:'Seminary 为神学院，原“修道院”不准确。',37:'Magna 是名称组成部分，不能据此把一颗农业行星变成恒星分类“巨星”。',47:'Q’arl’s 的s为所有格，不是人名中多出的“斯”。',55:'fortified 表示修筑防御工事，不是吸积盘物理性质得到强化。',61:'Astra Telepathica 是星语部，此行原译漏机构；station不必然是太空站。',111:'by extension 表示赤地星因属于该星系而随其定位，不是赤地星本身发生延伸。保留来源之间的归属冲突。'},terms=[('Nachmund Gauntlet','纳克蒙德走廊'),('Nachmund Sub-Sector','纳克蒙德次星区'),('Nachmund Rift War','纳克蒙德裂隙战争'),('Centor\'s Landing','森托登陆地'),('Cholaris','乔拉里斯'),('Immaterium Surge Station','非物质界涌动站'),('Jagdeth Magna','贾格迪斯·马格纳'),('Q\'arl\'s Rim','卡尔之缘'),('Seminary World','神学院世界'),('Nonavore','诺纳沃尔'),('Sanguis System','赤血星系')])
save(922,{2:'光环群星分布在朦胧星域的外围边疆。',7:'这些恒星极其古老，稀疏地散布在直径约二十万光年的范围内，其中一些聚成星群。这片光环区域几乎未经探索，适宜居住的星系可能寥寥无几。它在帝国中名声不祥，许多人认为那里幽魂徘徊，潜藏未知的恐怖。许多深入光环群星的探险队从此一去不返。',9:'区域内有一处名为“光环疤痕”的亚空间扰动，使穿越该区域几乎不可能。',13:'埃克尼利霍——曾藏有名为“众神之息”的古代造物。'},notes={7:'保持 probably 与许多人认为的限定，不将传说中的恐怖直接作为已证实事实。二十万光年为设定底稿提供的尺度。'},terms=[('Halo Stars','光环群星'),('Halo Scar','光环疤痕'),('Breath of the Gods','众神之息'),('Exniliho','埃克尼利霍')])
save(923,{13:'生产等级：III-Prima（原稿暂译三级上等）。',15:'什一税等级：Aptus Non（原稿暂译特级免税）。',17:'卢修斯是一颗铸造世界，也是星象泰坦军团的母星；该军团又称“亚空间跑者”。马卡里乌斯级超重型战斗坦克同样发源于此。',22:'行星之名取自一种名为光金（Luciun）的独特合金，它以坚固耐用著称。卢修斯军队用光金制造战甲和武器，因此能更好地承受轻武器火力。',26:'卢修斯是一颗空心世界，被列为帝国的重大超自然奇观之一。它参与了一场宏大实验，照理说早该因此毁灭十余次，却仍然存在。曾经空无一物的核心中央，悬着一颗人造太阳——巨大的聚变反应堆，为上方遍布地层的工业设施供能。尽管许多技术祭司争相认领功劳，却无人真正知道这颗能源核心如何诞生。近乎无穷的能源使卢修斯成为军工生产重镇，出产多种枪炮与载具。当地的铁骑兵和沙丘爬行者，在各护教军军团中以好战著称。星象军团的泰坦首席则在卢修斯上城的克隆学院接受训练。',28:'卢修斯纹章中的花饰字母被灼刻在行星表面，每一处细节从上到下都约十二英里长。',30:'卢修斯的铸造厂以生产卢修斯型战犬级侦察泰坦与卢修斯型空降舱著称，同时也大量制造各种型号的马卡里乌斯坦克。',33:'这颗星球曾经历灾难性的教化分裂，险些在内爆中释放足以撕裂现实的力量。如今，人们只敢低声谈起此事。',35:'第四十一千年，利维坦虫巢舰队入侵卢修斯。机械修会部队血战数月，最终赢得消耗战、逐退泰伦：卢修斯不断翻修机兵、回收机械部件，虫群的消耗与补充速度终究无法与之匹敌。',38:'卢修斯生产多种自有型号：',51:'Lucius pattern Cyclops Demolition Vehicle 卢修斯型独眼巨人爆破车',54:'Lucius pattern Warlord Titan 卢修斯型战将级泰坦',56:'Lucius Pattern Reaver Titan 卢修斯型掠夺者级泰坦',58:'Lucius Pattern Warhound Titan 卢修斯型战犬级泰坦',72:'伊卡洛斯式五型个人空降装置——星界军空降部队使用的一种重力伞。'},notes={17:'源文此处将Macharius称超重型，而后文图注称重型坦克；保留所给资料的分类差异，不无据抹平。',26:'Tech-Priests 原“技术深度”为明显误译，依官方技术祭司。Overcity 指上城，不是城市上空；Princeps为驾驶与指挥泰坦的首席，非笼统首领。',28:'illuminated letter 在徽章语境为装饰性花饰字母，不必然指字母自身发光。dozen为十二，不译十几。',51:'GW09第9页与GW10第8页可直接核对Cyclops Demolition Vehicle＝独眼巨人爆破车；附加Lucius型不因此声称完整型号已核官方。',54:'Warlord/Reaver/Warhound按已核GW09/GW10第5页分别为战将级、掠夺者级、战犬级泰坦；完整卢修斯型号仍是词根参考。'},terms=[('Lucius (Forge World)','卢修斯（铸造世界）'),('Luciun','光金'),('Supernatura Majoris','重大超自然奇观'),('Clone Academy','克隆学院'),('Overcity','上城'),('Inculcata Schism','教化分裂'),('Type Five Icarus-pattern Personal Descent Unit','伊卡洛斯式五型个人空降装置')])
save(924,{5:'名称：迪马默（原稿另译迪马玛尔）。',11:'类别：红衣主教世界。',13:'迪马默是朦胧星域中的一颗帝国世界。',16:'迪马默以两件事闻名：光明同盟在此成立，而推翻高戈·范迪尔、后来成为教宗的塞巴斯蒂安·托尔也出生于此。它还是第一颗公开违抗范迪尔、宣告他为异端的行星。',18:'迪马默居民过去曾与法比乌斯·拜尔打交道，在当地，他被称为“化学大师”。',21:'858.M41年，乌斯维方舟世界的灵族毫无预警地袭击迪马默，动机不明。鲜血玫瑰修会的炽天使小队长阿梅尔达率部发动大胆反击，杀死了灵族大先知。'},title='迪马默 Dimmamar',notes={5:'沿核心及866篇Dimmamar＝迪马默，保留旧名对照。',21:'Seraphim Superior 是率领炽天使的队长职衔，不是另一个“高阶炽天使”种族或兵种；全职衔中文仍为暂定。'},terms=[('Chem-master','化学大师'),('Seraphim Superior','炽天使小队长'),('Amelda','阿梅尔达')])
save(925,{5:'名称：塞浦拉·蒙迪（原稿另译凯普拉·蒙迪）。',13:'塞浦拉·蒙迪既是铸造世界，也是朦胧星域的行政与舰队中枢。行星轨道上设有一座星域堡垒，为整个朦胧星域的舰队行动提供基地，由一名内政部主管直接掌管。',16:'分析学院设于塞浦拉·蒙迪。',19:'大远征期间，早期极限战士从欧克手中解救了这颗星球，使其并入帝国。这里最早独立设计的战列舰型号是歼灭者级。',23:'罗保特·基里曼复活、大裂隙形成后，塞浦拉·蒙迪成为被隔绝在帝国暗面的世界之一。',26:'Cypra Mundi pattern Lightning 塞浦拉·蒙迪型闪电',28:'Cypra Mundi pattern Marauder Bomber 塞浦拉·蒙迪型掠夺者轰炸机',30:'Cypra Mundi pattern Marauder Destroyer 塞浦拉·蒙迪型掠夺者毁灭机'},title='塞浦拉·蒙迪 Cypra Mundi',notes={13:'Administratum Master 是内政部主管人员，不等于整个内政部的部长。',19:'unique Battleship design 指独有的战列舰设计型号，不是某一艘战舰。',23:'Dark Imperium 在此为Imperium Nihilus同义地理称呼，统一帝国暗面，不误作另一国家黑暗帝国。',30:'Marauder Destroyer为飞行载具型号，原“掠夺者毁灭者”未显示其类别；暂沿词根译掠夺者毁灭机，官方待核。'},terms=[('Collegium Analytica','分析学院'),('Annihilator Class','歼灭者级（战列舰）'),('Marauder Destroyer','掠夺者毁灭机')])
